SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(7*10^9);Alarm(1700);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");load "work/deg10/continuation_20261031b/C48/inputs/portable_inputs.m";load "work/deg10/continuation_20261031b/C48/inputs/pair_af_place_linear.m";load "work/deg10/continuation_20261031b/C48/bucket_forward_default.m";
root:="work/deg10/continuation_20261031b/C48/";k:=GF(5);PK:=PolynomialRing(k);B<t>:=FunctionField(k);R<Y>:=PolynomialRing(B);
function Rat(v)return B!(PK!v[1])/B!(PK!v[2]);end function;F<y>:=FunctionField(R![Rat(v):v in PortableFieldEquation]);assert Genus(F)eq 13;
function FF(v)return F![Rat(z):z in v];end function;OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);fb:=[];for i in[1..#PortableDegrees]do O:=PortableFlags[i]eq 1 select OF else OI;J:=ideal<O|[FF(v):v in PortableIdealBases[i]]>;p:=Place(J);assert Degree(p)eq PortableDegrees[i];Append(~fb,p);end for;
A:=Divisor(fb[801]);assert Degree(A)eq 1;Z:=FreeAbelianGroup(9);G,q:=quo<Z|[Z!v:v in PortableRelations]>;fc:=[q(Z!v):v in PortableClasses];ac:=fc[801];GQ,pi:=quo<G|[q(Z!v):v in PortableRationalCusps]cat[ac]>;assert #GQ eq 4608;allowed:=AssociativeArray();allowed[0]:={GQ!0};allowed[1]:={pi(q(Z!PortableCuspClasses[i])):i in[1..#PortableCuspDegrees]|PortableCuspDegrees[i]eq 1};coords:=[FF(v):v in PortableCoordinates];plane:=[F.1,F!B.1];ph,wh:=C48BucketDirectRR(F,fb,fc,G,A,root cat TAG cat "_class.log");src:=eval Read(root cat "high_character_targets.m");fs:=AssociativeArray();for z in src[1]do fs[z[1]]:=ext<k|PK!z[2]>;end for;
function UV(b,c)if 1-c eq 0 then return false,[];end if;t:=2*b/(1-c)-1;if t eq 0 then return false,[];end if;qq:=((1-c)*t^2-2)/(2*t);den:=t*(qq^2+1)+2*qq;if den*qq eq 0 then return false,[];end if;ss:=t*(qq^2-1)/den;dd:=(ss+2)/qq;return true,[(ss+dd)/2,(ss-dd)/2];end function;
rows:=[* *];left:=[];print "D31B_C48_HIGH_CLASS_FRAME_READY",SHARD,#fb,Cputime(tt);
for ci in[1..20]do d,ky,e,n:=Explode(src[2][ci]);K:=fs[d];bc:=[Evaluate(PK!ky[1..d],K.1),Evaluate(PK!ky[d+1..2*d],K.1)];ok,uv:=UV(bc[1],bc[2]);pt:=ok select C48PairAFPlaceLinear(plane,uv)else C48PairAFPlaceLinear(coords,bc);assert Degree(pt)eq e and e*n eq d;
 if e le 5 then ii:=Index(fb,pt);else ii:=0;end if;if ii gt 0 then cl0:=fc[ii]-e*ac;else cl0:=ph(Divisor(pt)-e*A);end if;cl:=n*cl0;pass:=-pi(cl)in allowed[10-d];Append(~rows,[*ci,d,e,n,Eltseq(cl),Eltseq(pi(cl)),pass*]);if pass then Append(~left,ci);end if;if #rows mod 50 eq 0 then Write(root cat TAG cat "_progress.m",Sprint([*rows,left*]):Overwrite:=true);print "D31B_C48_HIGH_CLASS_PROGRESS",SHARD,#rows,#left,Cputime(tt);end if;
end for;
expected:=eval Read(root cat "default_profile_expected.m");assert &and[rows[i][1]eq expected[i][1]and rows[i][5]eq expected[i][2]:i in[1..20]];Write(root cat TAG cat ".m",Sprint([*rows,left,[Eltseq(v):v in Rows(RelationMatrix(GQ))],[Eltseq(pi(q(Z.i))):i in[1..9]]*]):Overwrite:=true);fprintf wh,"]\n";Flush(wh);print "D31B_C48_DEFAULT_PROFILE_COMPLETE",SHARD,#rows,#left,Cputime(tt);quit;
